draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
ctx.textAlign = "center";
var padL = 34, padR = 18, padT = 26, padB = 34;
var lmin = 90, lmax = 2400;
function X(lam) {
  return padL + (Math.log(lam) - Math.log(lmin)) / (Math.log(lmax) - Math.log(lmin)) * (W - padL - padR);
}
var axisY = H - padB;

// axis
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, axisY);
ctx.lineTo(W - padR, axisY);
ctx.stroke();
var ticks = [100, 200, 400, 800, 1600];
var i;
for (i = 0; i < ticks.length; i++) {
  var xt = X(ticks[i]);
  ctx.strokeStyle = C.rule;
  ctx.beginPath();
  ctx.moveTo(xt, axisY);
  ctx.lineTo(xt, axisY + 4);
  ctx.stroke();
  ctx.fillStyle = C.rule;
  ctx.fillText(String(ticks[i]), xt, axisY + 14);
}
ctx.fillStyle = C.ink;
ctx.fillText("wavelength (nm, log scale)", W / 2, H - 6);

// visible band
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.35;
ctx.fillRect(X(400), padT, X(700) - X(400), axisY - padT);
ctx.globalAlpha = 1;
ctx.fillStyle = C.faint;
ctx.fillText("visible", (X(400) + X(700)) / 2, padT - 12);

var names = ["Lyman", "Balmer", "Paschen"];
var rowH = (axisY - padT) / 3;
var f;
for (f = 1; f <= 3; f++) {
  var yTop = padT + (f - 1) * rowH + 6;
  var yBot = yTop + rowH - 16;
  var col = (f === 2) ? C.accent : C.figure;
  var n2;
  for (n2 = f + 1; n2 <= 14; n2++) {
    var dE = 13.6 * (1 / (f * f) - 1 / (n2 * n2));
    var lam = 1240 / dE;
    var x = X(lam);
    ctx.strokeStyle = col;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(x, yTop);
    ctx.lineTo(x, yBot);
    ctx.stroke();
  }
  // series limit
  var lamLim = 1240 / (13.6 / (f * f));
  ctx.strokeStyle = C.ink;
  ctx.setLineDash([2, 3]);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(X(lamLim), yTop - 4);
  ctx.lineTo(X(lamLim), yBot + 4);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText(names[f - 1] + " (ends on n=" + f + ")", padL + 4, yTop - 2);
  ctx.textAlign = "center";
  ctx.fillStyle = C.rule;
  ctx.fillText("limit " + lamLim.toFixed(0), X(lamLim) + 30, yBot + 2);
}
ctx.lineWidth = 1;
